<?php

declare(strict_types=1);
require __DIR__.'/notes-visibility.php';
$ownershipProject=newNotesProject($owner,'Transferências seguras');
foreach([$member=>'member',$viewer=>'viewer',$users['unverified']['id']=>'member'] as $uid=>$role){$pdo->prepare('INSERT IGNORE INTO tenant_users(tenant_id,user_id) VALUES (?,?)')->execute([$tenant,$uid]);$pdo->prepare('INSERT INTO project_members(tenant_id,project_id,user_id,role) VALUES (?,?,?,?)')->execute([$tenant,$ownershipProject,$uid,$role]);}
$columnId=(int)$boards->state($owner,$ownershipProject)['columns'][0]['id'];
$note=$notes->create($owner,"Conteúdo original\nSegunda linha",$ownershipProject,'Título original','orange');$original=appearanceRow($note);
$recipients=$notes->recipients($owner,$note);check(array_column($recipients,'id')==[$member,$viewer],'Somente outros membros verificados, ordenados por nome');check(array_keys($recipients[0])===['id','name'],'Destinatários sem e-mail');
$inbox=$notes->create($owner,'Inbox não transfere',null);noteError(422,fn()=>$notes->recipients($owner,$inbox),'Inbox sem lista de destinatários');noteError(422,fn()=>$notes->transfer($owner,$inbox,$member,true,1),'Inbox não transfere');noteError(422,fn()=>$notes->convert($owner,$inbox,$ownershipProject,$columnId,'Título confirmado',1),'Inbox não converte');
noteError(422,fn()=>$notes->transfer($owner,$note,$member,false,1),'Confirmação obrigatória');noteError(422,fn()=>$notes->transfer($owner,$note,$owner,true,1),'Não transfere para si');noteError(422,fn()=>$notes->transfer($owner,$note,$outside,true,1),'Externo ao projeto');noteError(422,fn()=>$notes->transfer($owner,$note,$users['unverified']['id'],true,1),'Conta não verificada indisponível');noteError(409,fn()=>$notes->transfer($owner,$note,$member,true,2),'Versão obsoleta');
$csrf=boardLogin($users['owner']['email']);check(noteRequest('/notes/'.$note.'/transfer',['recipient_id'=>$member,'confirm'=>'1','revision'=>1])[0]===419,'CSRF transferência');check(noteRequest('/notes/'.$note.'/transfer',['_token'=>$csrf,'recipient_id'=>$member,'revision'=>1])[0]===422,'Confirmação HTTP');check(noteRequest('/notes/'.$note.'/transfer',['_token'=>$csrf,'recipient_id'=>$member,'confirm'=>'1','revision'=>1])[0]===200,'Transferência HTTP');
$after=appearanceRow($note);check((int)$after['user_id']===$member&&(int)$after['created_by']===$owner&&(int)$after['revision']===2,'Novo proprietário e criador original preservados');foreach(['tenant_id','project_id','body','title','color','created_at','visibility'] as $field)check($after[$field]===$original[$field],'Preserva '.$field);
check(!in_array($note,array_column($notes->page($owner,$ownershipProject)['items'],'id')),'Remetente deixa de ver nota privada');check(in_array($note,array_column($notes->page($member,$ownershipProject)['items'],'id')),'Destinatário recebe nota privada no projeto');
foreach([fn()=>$notes->update($owner,$note,'Intrusão'),fn()=>$notes->delete($owner,$note),fn()=>$notes->transfer($owner,$note,$viewer,true,2),fn()=>$notes->recipients($owner,$note),fn()=>$notes->convert($owner,$note,$ownershipProject,$columnId,'Intrusão',2)] as $operation)noteError(404,$operation,'Antigo dono perde privilégios');
$notes->update($member,$note,$original['body'],['visibility'=>'project','revision'=>2]);$notes->transfer($member,$note,$viewer,true,3);
$listed=$notes->page($owner,$ownershipProject)['items'][0];check((int)$listed['involved'][0]['id']===$viewer&&(int)$listed['involved'][0]['is_owner']===1,'Proprietário atual aparece primeiro');$people=array_map('intval',array_column($listed['involved'],'id'));sort($people);$expected=[$owner,$member,$viewer];sort($expected);check($people===$expected,'Criador e destinatários derivados da auditoria, sem duplicação');
noteError(403,fn()=>$notes->convert($viewer,$note,$ownershipProject,$columnId,'Não pode converter',4),'Novo proprietário visualizador não cria tarefa');$notes->transfer($viewer,$note,$owner,true,4);
$pdo->prepare('DELETE FROM project_members WHERE tenant_id=? AND project_id=? AND user_id=?')->execute([$tenant,$ownershipProject,$member]);$listed=$notes->page($owner,$ownershipProject)['items'][0];check(!in_array($member,array_map('intval',array_column($listed['involved'],'id'))),'Histórico não expõe envolvido sem acesso atual');
$notes->update($owner,$note,$original['body'],['visibility'=>'private','revision'=>5]);$listed=$notes->page($owner,$ownershipProject)['items'][0];check(array_map('intval',array_column($listed['involved'],'id'))===[$owner],'Privado indica somente proprietário autorizado');
foreach([''," \t ",str_repeat('á',201),"Título\ninválido",[],null] as $title)noteError(422,fn()=>$notes->convert($owner,$note,$ownershipProject,$columnId,$title,6),'Título obrigatório e validado');noteError(409,fn()=>$notes->convert($owner,$note,$ownershipProject,$columnId,'Título confirmado',1),'Conversão obsoleta');noteError(422,fn()=>$notes->convert($owner,$note,$projectId,$column,'Título confirmado',6),'Não troca projeto na conversão');noteError(422,fn()=>$notes->convert($owner,$note,$ownershipProject,$column,'Título confirmado',6),'Não aceita coluna de outro projeto');
$taskId=$notes->convert($owner,$note,$ownershipProject,$columnId,'Título confirmado na conversão',6);$taskRow=$pdo->query('SELECT * FROM tasks WHERE id='.$taskId)->fetch();check($taskRow['title']==='Título confirmado na conversão'&&$taskRow['description']===$original['body'],'Título confirmado e descrição integral');check((int)$pdo->query('SELECT COUNT(*) FROM quick_notes WHERE id='.$note)->fetchColumn()===0,'Conversão remove nota');$conversion=json_decode($pdo->query('SELECT after_state FROM quick_note_events WHERE note_id='.$note." AND action='converted'")->fetchColumn(),true);check((int)$conversion['task_id']===$taskId&&(int)$conversion['created_by']===$owner,'Auditoria preserva criador e tarefa resultante');
$pdo->prepare("INSERT INTO project_members(tenant_id,project_id,user_id,role) VALUES (?,?,?,'member')")->execute([$tenant,$ownershipProject,$member]);
$recipientTaskNote=$notes->create($owner,'Tarefa do novo proprietário',$ownershipProject);$notes->transfer($owner,$recipientTaskNote,$member,true,1);$recipientTask=$notes->convert($member,$recipientTaskNote,$ownershipProject,$columnId,'Tarefa do novo proprietário',2);check((int)$pdo->query('SELECT created_by FROM tasks WHERE id='.$recipientTask)->fetchColumn()===$member&&(int)$pdo->query('SELECT user_id FROM task_assignees WHERE task_id='.$recipientTask)->fetchColumn()===$member,'Conversão atribui ao proprietário atual');
$rollback=$notes->create($owner,'Transferência atômica',$ownershipProject);$snapshot=appearanceRow($rollback);$pdo->exec("CREATE TRIGGER reject_ownership_audit BEFORE INSERT ON quick_note_events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='rollback transfer'");try{try{$notes->transfer($owner,$rollback,$member,true,1);check(false,'Falha da auditoria esperada');}catch(PDOException){}check(appearanceRow($rollback)===$snapshot,'Rollback da propriedade e versão');}finally{$pdo->exec('DROP TRIGGER reject_ownership_audit');}
$revokedTarget=$notes->create($owner,'Destinatário revogado',$ownershipProject);$notes->recipients($owner,$revokedTarget);$pdo->prepare('DELETE FROM project_members WHERE tenant_id=? AND project_id=? AND user_id=?')->execute([$tenant,$ownershipProject,$member]);noteError(422,fn()=>$notes->transfer($owner,$revokedTarget,$member,true,1),'Reconfere destinatário no envio');$pdo->prepare("INSERT INTO project_members(tenant_id,project_id,user_id,role) VALUES (?,?,?,'member')")->execute([$tenant,$ownershipProject,$member]);
function ownershipRace(array $operations):array{$jobs=[];foreach($operations as [$action,$actor,$note,$target,$column,$revision]){$pipes=[];$process=proc_open([PHP_BINARY,__DIR__.'/notes-ownership-child.php',$action,(string)$actor,(string)$note,(string)$target,(string)$column,(string)$revision],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__));check(is_resource($process),'Processo de propriedade');fclose($pipes[0]);$jobs[]=[$process,$pipes];}$results=[];foreach($jobs as [$process,$pipes]){$results[]=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);check(proc_close($process)===0,'Concorrência: '.$error);}sort($results);return $results;}
$race=$notes->create($owner,'Transferir uma vez',$ownershipProject);check(ownershipRace([['transfer',$owner,$race,$member,0,1],['transfer',$owner,$race,$viewer,0,1]])===['conflict','ok'],'Uma transferência vence');check((int)$pdo->query('SELECT COUNT(*) FROM quick_note_events WHERE note_id='.$race." AND action='transferred'")->fetchColumn()===1,'Uma auditoria de transferência');
$versus=$notes->create($owner,'Transferir ou converter',$ownershipProject);check(ownershipRace([['transfer',$owner,$versus,$member,0,1],['convert',$owner,$versus,$ownershipProject,$columnId,1]])===['conflict','ok'],'Transferência versus conversão tem um vencedor');
$crossProject=newNotesProject($owner,'Transferência cruzada');$pdo->prepare("INSERT INTO project_members(tenant_id,project_id,user_id,role) VALUES (?,?,?,'member')")->execute([$tenant,$crossProject,$member]);$crossA=$notes->create($owner,'A',$ownershipProject);$crossB=$notes->create($member,'B',$crossProject);check(ownershipRace([['transfer',$owner,$crossA,$member,0,1],['transfer',$member,$crossB,$owner,0,1]])===['ok','ok'],'Transferências opostas em projetos distintos sem perda');
$archivedTransferProject=newNotesProject($owner,'Transferência arquivada');$pdo->prepare("INSERT INTO project_members(tenant_id,project_id,user_id,role) VALUES (?,?,?,'member')")->execute([$tenant,$archivedTransferProject,$member]);$archivedTransfer=$notes->create($owner,'Arquivo',$archivedTransferProject);$projects->change($owner,$archivedTransferProject,'archive');noteError(409,fn()=>$notes->transfer($owner,$archivedTransfer,$member,true,1),'Projeto arquivado não transfere');
$privateActor=$notes->create($owner,'Sem acesso ao projeto',$ownershipProject);$pdo->prepare('DELETE FROM project_members WHERE tenant_id=? AND project_id=? AND user_id=?')->execute([$tenant,$ownershipProject,$owner]);noteError(404,fn()=>$notes->transfer($owner,$privateActor,$member,true,1),'Reconfere remetente');
echo "OK: transferência confirmada, propriedade, criador, envolvidos autorizados, título obrigatório, projeto fixo, CSRF, revogação, rollback e concorrência transferência/conversão.\n";
